import type { ModulesLock } from "./lock";
import type { LoadedModule } from "./manifests";
import { MOD_PATHS } from "./paths";

/**
 * Pure, deterministic builders for every generated file (registries, env
 * modules, route stubs, transpile list). Inputs are the loaded modules
 * (already sorted by slug); same inputs always produce byte-identical output —
 * the drift test (apps/nextjs/src/mod/registry-drift.test.ts) recomputes these
 * and compares against the committed files.
 *
 * No timestamps, no environment reads, no formatting passes: output is final.
 */

export interface GeneratedFile {
  /** Repo-relative posix path. */
  path: string;
  content: string;
  /** Owning module — set for route stubs (sync records them in the lock). */
  slug?: string;
}

const HEADER = `// GENERATED by \`pnpm mod sync\` — DO NOT EDIT.
// Recomputed from modules/*/module.config.ts; a stale copy fails
// \`pnpm test\` via apps/nextjs/src/mod/registry-drift.test.ts.
`;

const ESLINT_OFF = "/* eslint-disable */\n";

const ident = (slug: string): string => slug.replace(/-/g, "_");

const sysMod = (m: LoadedModule["manifest"]): boolean =>
  m.routes.web.some((r) => r.mount !== undefined) ||
  m.routes.native.some((r) => r.mount !== undefined);

const quote = (s: string): string => JSON.stringify(s);

/** An object key the way Prettier writes it (quoted only when needed). */
export const propKey = (s: string): string =>
  /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(s) ? s : quote(s);

interface NavLiteral {
  key: string;
  module: string;
  title: string;
  href: string;
  icon?: string;
  order: number;
  audience: "everyone" | "staff" | "members";
  /** Web submenu entries: the key of the entry they're listed under. */
  parent?: string;
}

function navLiterals(
  mods: LoadedModule[],
  platform: "web" | "native",
): NavLiteral[] {
  const out: NavLiteral[] = [];
  for (const { manifest: m } of mods) {
    if (!m.platforms[platform]) continue;
    m.nav[platform].forEach((entry) => {
      // Same key the boot reconcile gives the nav-items row.
      const key = `mod:${m.slug}:${entry.href}`;
      out.push({
        key,
        module: m.slug,
        title: entry.title,
        href: entry.href,
        icon: entry.icon,
        order: entry.order,
        audience: entry.audience,
      });
      // Web submenus: each child is its own row, ordered right after its
      // parent in declared order (fractional, so it never collides with
      // another module's whole-number order).
      if (platform !== "web") return;
      (entry as (typeof m.nav.web)[number]).children.forEach((child, i) => {
        out.push({
          key: `mod:${m.slug}:${child.href}`,
          module: m.slug,
          title: child.title,
          href: child.href,
          icon: child.icon,
          order: entry.order + (i + 1) / 100,
          audience: child.audience,
          parent: key,
        });
      });
    });
  }
  return out;
}

function renderNav(items: NavLiteral[], indent: string): string {
  if (items.length === 0) return "[]";
  const rows = items.map(
    (n) =>
      `${indent}  { key: ${quote(n.key)}, module: ${quote(n.module)}, title: ${quote(n.title)}, href: ${quote(n.href)}, ${n.icon ? `icon: ${quote(n.icon)}, ` : ""}order: ${n.order}${n.audience !== "everyone" ? `, audience: ${quote(n.audience)}` : ""}${n.parent ? `, parent: ${quote(n.parent)}` : ""} },`,
  );
  return `[\n${rows.join("\n")}\n${indent}]`;
}

function renderInstalled(mods: LoadedModule[]): string {
  if (mods.length === 0) return "[]";
  const rows = mods.map(
    ({ manifest: m }) =>
      `  { slug: ${quote(m.slug)}, name: ${quote(m.name)}, version: ${quote(m.version)}, system: ${sysMod(m)}${m.access.check ? `, accessCheck: ${quote(m.access.check)}` : ""} },`,
  );
  return `[\n${rows.join("\n")}\n]`;
}

const SHARED_TYPES = `export interface ModInstalled {
  slug: string;
  name: string;
  version: string;
  /** True when the app shell depends on this module's mounts (e.g. the home screen). */
  system: boolean;
  /** SQL function deciding if the current user may use the module (manifest access.check). */
  accessCheck?: string;
}

export interface ModNavDefault {
  key: string;
  module: string;
  title: string;
  href: string;
  icon?: string;
  order: number;
  /** Default audience; omitted = everyone. */
  audience?: "everyone" | "staff" | "members";
  /** Web submenu entry: the key of the entry it's listed under. */
  parent?: string;
}
`;

/**
 * apps/nextjs/src/mod/registry.data.generated.ts — plain data only (no React,
 * no module imports), so server code and CLIs (the boot/seed nav reconcile,
 * the enablement gate) can read the installed set without pulling every
 * module's web UI into their import graph.
 */
export function buildNextDataRegistry(mods: LoadedModule[]): string {
  return `${ESLINT_OFF}${HEADER}${SHARED_TYPES}
/** Every installed module (from the vendored manifests). */
export const modInstalled: ModInstalled[] = ${renderInstalled(mods)};

/**
 * Manifest nav DEFAULTS — seeded into the CMS-driven menu by the boot
 * reconcile (lib/mod/reconcile-nav.ts), never rendered directly.
 */
export const modNavDefaults: { web: ModNavDefault[]; native: ModNavDefault[] } = {
  web: ${renderNav(navLiterals(mods, "web"), "  ")},
  native: ${renderNav(navLiterals(mods, "native"), "  ")},
};

export function hasModule(slug: string): boolean {
  return modInstalled.some((e) => e.slug === slug);
}
`;
}

/** apps/nextjs/src/mod/registry.client.generated.ts */
export function buildNextClientRegistry(mods: LoadedModule[]): string {
  const webMods = mods.filter((e) => e.manifest.platforms.web);
  const widgetMods = webMods.filter((e) => e.manifest.widgets.web);
  const iconNames = [
    ...new Set(
      webMods.flatMap((e) =>
        e.manifest.nav.web
          .flatMap((n) => [n, ...n.children])
          .flatMap((n) => (n.icon ? [n.icon] : [])),
      ),
    ),
  ].sort();

  const imports: string[] = ['import type * as React from "react";'];
  if (iconNames.length > 0) {
    imports.push(
      `import { ${iconNames.join(", ")} } from "@tabler/icons-react";`,
    );
  }
  for (const e of widgetMods) {
    imports.push(
      `import { ${e.manifest.widgets.web} as widget_${ident(e.manifest.slug)} } from "${e.packageName}/web";`,
    );
  }
  const adapterMods = webMods.filter((e) => e.manifest.adapter?.web);
  for (const e of adapterMods) {
    imports.push(
      `import { ${e.manifest.adapter?.web} as adapter_${ident(e.manifest.slug)} } from "${e.packageName}/web";`,
    );
  }
  const clientAdapters =
    adapterMods.length === 0
      ? "[]"
      : `[\n${adapterMods
          .map(
            (e) =>
              `  { slug: ${quote(e.manifest.slug)}, target: ${quote(e.manifest.adapter?.for ?? "")}, adapter: adapter_${ident(e.manifest.slug)} },`,
          )
          .join("\n")}\n]`;

  const widgets =
    widgetMods.length === 0
      ? "[]"
      : `[\n${widgetMods
          .map(
            (e) =>
              `  { slug: ${quote(e.manifest.slug)}, Widget: widget_${ident(e.manifest.slug)} },`,
          )
          .join("\n")}\n]`;

  const icons =
    iconNames.length === 0
      ? "{}"
      : `{\n${iconNames.map((n) => `  ${n}: ${n},`).join("\n")}\n}`;

  return `${ESLINT_OFF}${HEADER}${imports.join("\n")}

// Plain data (installed set, nav defaults, hasModule) lives in the data
// registry so server code can import it without the web UI below.
export * from "./registry.data.generated";

/** Dashboard widgets declared by installed modules (web components). */
export const modWidgets: { slug: string; Widget: React.ComponentType }[] = ${widgets};

/** Icon names referenced by module nav defaults → components. */
export const modIcons: Record<string, React.ComponentType<{ className?: string }>> = ${icons};

/**
 * Client adapters (manifest adapter.web) — handed to ModAdaptersProvider
 * (enabled modules only); the target reads them with useModAdapters().
 */
export const modClientAdapters: { slug: string; target: string; adapter: unknown }[] = ${clientAdapters};
`;
}

/** apps/nextjs/src/mod/registry.server.generated.ts */
/**
 * `registerModAdapters({...})` — lazy loaders for every server adapter,
 * grouped by target. Shared by the server and payload registries.
 */
function adapterLoaders(mods: LoadedModule[]): string | null {
  const byTarget = new Map<string, LoadedModule[]>();
  for (const e of mods) {
    const a = e.manifest.adapter;
    if (!a?.server) continue;
    byTarget.set(a.for, [...(byTarget.get(a.for) ?? []), e]);
  }
  if (byTarget.size === 0) return null;
  const targets = [...byTarget.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(
      ([target, rows]) =>
        `  ${propKey(target)}: [\n${rows
          .map(
            (e) =>
              `    { slug: ${quote(e.manifest.slug)}, load: () => import(${quote(`${e.packageName}/server`)}) },`,
          )
          .join("\n")}\n  ],`,
    );
  return `// Adapters (manifest adapter.for), loaded lazily on first use so the
// Payload CLI never evaluates server-only adapter code.
registerModAdapters({\n${targets.join("\n")}\n});`;
}

export function buildNextServerRegistry(mods: LoadedModule[]): string {
  const serverMods = mods.filter((e) => e.manifest.server.routes);
  const publicMods = mods.filter((e) => e.manifest.server.publicRoutes);
  const serviceMods = mods.filter((e) => e.manifest.server.services);
  const loaders = adapterLoaders(mods);
  const imports: string[] = [];
  for (const e of mods) {
    const names = [
      ...(e.manifest.server.routes
        ? [`routes as routes_${ident(e.manifest.slug)}`]
        : []),
      ...(e.manifest.server.publicRoutes
        ? [`publicRoutes as publicRoutes_${ident(e.manifest.slug)}`]
        : []),
      ...(e.manifest.server.services
        ? [`services as services_${ident(e.manifest.slug)}`]
        : []),
    ];
    if (names.length > 0) {
      imports.push(
        `import { ${names.join(", ")} } from "${e.packageName}/server";`,
      );
    }
  }
  const table = (rows: LoadedModule[], prefix: string): string =>
    rows.length === 0
      ? "{}"
      : `{\n${rows
          .map(
            (e) =>
              `  ${quote(e.manifest.slug)}: ${prefix}_${ident(e.manifest.slug)},`,
          )
          .join("\n")}\n}`;

  const kitImport = loaders
    ? `import { type ModPublicRouteTable, type ModRouteTable, type ModServices, registerModAdapters } from "@acme/mod-kit/server";`
    : `import type { ModPublicRouteTable, ModRouteTable, ModServices } from "@acme/mod-kit/server";`;

  return `${ESLINT_OFF}${HEADER}import "server-only";

${kitImport}
${imports.length > 0 ? `\n${imports.join("\n")}\n` : ""}
/** slug → authed route table, dispatched by /api/mod/[mod]/[[...route]]. */
export const modServerRoutes: Record<string, ModRouteTable> = ${table(serverMods, "routes")};

/** slug → PUBLIC route table (no session required; still rate-limited). */
export const modPublicRoutes: Record<string, ModPublicRouteTable> = ${table(publicMods, "publicRoutes")};

/**
 * slug → the module's host-facing services (manifest server.services). Host
 * code calls \`modServices.<slug>?.fn(...)\` instead of importing modules.
 */
export const modServices: Record<string, ModServices> = ${table(serviceMods, "services")};
${loaders ? `\n${loaders}\n` : ""}`;
}

/** apps/nextjs/src/mod/registry.payload.generated.ts */
export function buildNextPayloadRegistry(mods: LoadedModule[]): string {
  const cmsMods = mods.filter((e) => {
    const c = e.manifest.cms;
    return (
      c.collections.length > 0 ||
      c.globals.length > 0 ||
      c.hasPlugins ||
      c.hasMigrations ||
      c.hasSeed ||
      c.hasSettings ||
      c.settingsTabFor !== undefined ||
      c.hasCollectionTabs
    );
  });
  const loaders = adapterLoaders(mods);

  const imports = cmsMods.map(
    (e) =>
      `import * as payload_${ident(e.manifest.slug)} from "${e.packageName}/payload";`,
  );

  const spread = (cond: boolean, expr: string): string[] =>
    cond ? [expr] : [];

  const collections = cmsMods.flatMap((e) =>
    spread(
      e.manifest.cms.collections.length > 0,
      `  ...payload_${ident(e.manifest.slug)}.collections,`,
    ),
  );
  const collectionTabs = cmsMods.flatMap((e) =>
    spread(
      e.manifest.cms.hasCollectionTabs,
      `  ...payload_${ident(e.manifest.slug)}.collectionTabs,`,
    ),
  );
  // Adapters that contribute a settings TAB to another module's settings
  // global (cms.settingsTabFor) instead of owning their own — grouped by target.
  const contributorsByTarget = new Map<string, LoadedModule[]>();
  for (const e of cmsMods) {
    const target = e.manifest.cms.settingsTabFor;
    if (!target) continue;
    contributorsByTarget.set(target, [
      ...(contributorsByTarget.get(target) ?? []),
      e,
    ]);
  }
  // The settings expression for a module: its own definition, or — when
  // adapters target it — a composeSettingsTabs(...) over a generated const.
  const settingsExpr = (e: LoadedModule): string =>
    contributorsByTarget.has(e.manifest.slug)
      ? `${ident(e.manifest.slug)}Settings`
      : `payload_${ident(e.manifest.slug)}.settings`;
  const settingsConsts = [...contributorsByTarget.entries()].map(
    ([target, contribs]) => {
      const tabs = contribs
        .map((c) => `  payload_${ident(c.manifest.slug)}.settings`)
        .join(",\n");
      return `const ${ident(target)}Settings = composeSettingsTabs(payload_${ident(target)}.settings, [\n${tabs},\n]);`;
    },
  );

  const globals = cmsMods.flatMap((e) => [
    ...spread(
      e.manifest.cms.globals.length > 0,
      `  ...payload_${ident(e.manifest.slug)}.globals,`,
    ),
    ...spread(e.manifest.cms.hasSettings, `  ${settingsExpr(e)}.global,`),
  ]);
  const plugins = cmsMods.flatMap((e) =>
    spread(
      e.manifest.cms.hasPlugins,
      `  ...payload_${ident(e.manifest.slug)}.plugins,`,
    ),
  );
  const migrations = cmsMods.flatMap((e) =>
    spread(
      e.manifest.cms.hasMigrations,
      `  ...payload_${ident(e.manifest.slug)}.migrations,`,
    ),
  );
  const seeds = cmsMods.flatMap((e) =>
    spread(
      e.manifest.cms.hasSeed,
      `  ...payload_${ident(e.manifest.slug)}.seed,`,
    ),
  );
  const settings = cmsMods.flatMap((e) =>
    spread(
      e.manifest.cms.hasSettings,
      `  ${quote(e.manifest.slug)}: ${settingsExpr(e)},`,
    ),
  );

  const arr = (rows: string[]): string =>
    rows.length === 0 ? "[]" : `[\n${rows.join("\n")}\n]`;
  const obj = (rows: string[]): string =>
    rows.length === 0 ? "{}" : `{\n${rows.join("\n")}\n}`;

  const composeNames = [
    ...(collectionTabs.length > 0 ? ["composeCollectionTabs"] : []),
    ...(settingsConsts.length > 0 ? ["composeSettingsTabs"] : []),
  ];
  const composeImport =
    composeNames.length > 0
      ? `import { ${composeNames.join(", ")} } from "@acme/mod-kit/payload";\n`
      : "";
  const loaderImport = loaders
    ? `import { registerModAdapters } from "@acme/mod-kit/server";\n`
    : "";
  const collectionsExpr =
    collectionTabs.length > 0
      ? `composeCollectionTabs(${arr(collections)}, ${arr(collectionTabs)})`
      : arr(collections);

  return `${ESLINT_OFF}${HEADER}import type { CollectionConfig, Config, GlobalConfig } from "payload";

import type { ModuleSettings, ModSeedStep } from "@acme/mod-kit/payload";
${composeImport}${loaderImport}${imports.length > 0 ? `\n${imports.join("\n")}\n` : ""}
export interface ModPayloadMigration {
  name: string;
  up: (args: any) => Promise<void>;
  down: (args: any) => Promise<void>;
}
${settingsConsts.length > 0 ? `\n${settingsConsts.join("\n")}\n` : ""}
export const modCollections: CollectionConfig[] = ${collectionsExpr};

export const modGlobals: GlobalConfig[] = ${arr(globals)};

export const modPlugins: NonNullable<Config["plugins"]> = ${arr(plugins)};

export const modPayloadMigrations: ModPayloadMigration[] = ${arr(migrations)};

export const modSeedSteps: ModSeedStep[] = ${arr(seeds)};

/**
 * slug → settings definition. The fields render on the module's page in
 * /admin (kit-modules) — see payload/collections/KitModules.ts.
 */
export const modSettings: Record<string, ModuleSettings> = ${obj(settings)};

/**
 * Modules with their own admin settings component (manifest
 * admin.settingsComponent) — rendered on the module's page in /admin (or, for
 * an adapter, on \`page\`: its target module's page) through the kit's
 * ModuleAdminSettings wrapper (registry.admin.generated.tsx).
 */
export const modAdminSettings: { slug: string; page?: string }[] = ${arr(
    mods
      .filter((e) => e.manifest.admin.settingsComponent)
      .map((e) => {
        // An adapter's panel renders on its target module's page.
        const page = e.manifest.adapter?.for ?? e.manifest.cms.settingsTabFor;
        return `  { slug: ${quote(e.manifest.slug)}${page ? `, page: ${quote(page)}` : ""} },`;
      }),
  )};
${loaders ? `\n${loaders}\n` : ""}`;
}

/**
 * apps/nextjs/src/mod/registry.admin.generated.tsx — the modules' ./admin
 * settings components by slug. A client module imported only by the /admin
 * wrapper (payload/components/ModuleAdminSettings.tsx), so Payload's import
 * map stays static however many modules are installed.
 */
export function buildNextAdminRegistry(mods: LoadedModule[]): string {
  const adminMods = mods.filter((e) => e.manifest.admin.settingsComponent);
  const imports = adminMods.map(
    (e) =>
      `import { AdminSettings as admin_${ident(e.manifest.slug)} } from "${e.packageName}/admin";`,
  );
  const rows = adminMods.map(
    (e) => `  ${propKey(e.manifest.slug)}: admin_${ident(e.manifest.slug)},`,
  );
  return `"use client";

${ESLINT_OFF}${HEADER}import type { ComponentType } from "react";
${imports.length > 0 ? `\n${imports.join("\n")}\n` : ""}
/** slug → the module's \`./admin\` AdminSettings component. */
export const modAdminComponents: Record<string, ComponentType> = ${rows.length === 0 ? "{}" : `{\n${rows.join("\n")}\n}`};
`;
}

/** apps/nextjs/src/mod/env.generated.ts */
export function buildNextEnv(mods: LoadedModule[]): string {
  const envMods = mods.filter(
    (e) => e.manifest.env.hasServer || e.manifest.env.hasClient,
  );
  const imports = envMods.map(
    (e) =>
      `import modEnv_${ident(e.manifest.slug)} from "${e.packageName}/env";`,
  );

  const serverSpreads = envMods
    .filter((e) => e.manifest.env.hasServer)
    .map((e) => `  ...modEnv_${ident(e.manifest.slug)}.server,`);

  const clientRows: string[] = [];
  const runtimeRows: string[] = [];
  for (const e of envMods) {
    if (!e.manifest.env.hasClient) continue;
    for (const key of e.envClientKeys) {
      clientRows.push(
        `  NEXT_PUBLIC_${key}: modEnv_${ident(e.manifest.slug)}.client.${key},`,
      );
      runtimeRows.push(`  NEXT_PUBLIC_${key}: process.env.NEXT_PUBLIC_${key},`);
    }
  }

  const obj = (rows: string[]): string =>
    rows.length === 0 ? "{}" : `{\n${rows.join("\n")}\n}`;

  return `${ESLINT_OFF}${HEADER}${imports.length > 0 ? `${imports.join("\n")}\n\n` : ""}/** Merged server-only env shapes from installed modules (MOD_*). */
export const modServerEnv = ${obj(serverSpreads)};

/** Merged client env shapes (NEXT_PUBLIC_MOD_*). */
export const modClientEnv = ${obj(clientRows)};

/** Literal process.env reads (t3-env requires them for client vars). */
export const modClientRuntimeEnv = ${obj(runtimeRows)};
`;
}

/** The URL a native module route is served at (see buildStubs). */
function nativeRouteHref(
  slug: string,
  r: LoadedModule["manifest"]["routes"]["native"][number],
): string {
  if (r.mount === "index") return "/home";
  return r.path === "" ? `/a/${slug}` : `/a/${slug}/${r.path}`;
}

/** apps/expo/src/mod/registry.generated.ts */
export function buildExpoRegistry(mods: LoadedModule[]): string {
  const nativeMods = mods.filter((e) => e.manifest.platforms.native);
  const widgetMods = nativeMods.filter((e) => e.manifest.widgets.native);

  const imports: string[] = ['import type * as React from "react";'];
  // Side-effect imports: each native module's ./native entry loads at app
  // start (the root _layout imports this registry), so modules can register
  // native handlers on boot — e.g. notifications' setNotificationHandler.
  for (const e of nativeMods) {
    if (e.manifest.widgets.native) continue; // imported by name below
    if (e.manifest.routes.native.length === 0) continue; // no native entry
    imports.push(`import "${e.packageName}/native";`);
  }
  for (const e of widgetMods) {
    imports.push(
      `import { ${e.manifest.widgets.native} as widget_${ident(e.manifest.slug)} } from "${e.packageName}/native";`,
    );
  }

  // Menu-addressable screens (static routes only), keyed by URL href, so the
  // native tab bar can render whichever module staff put in each tab slot.
  const screenRows: string[] = [];
  let needsGate = false;
  for (const e of nativeMods) {
    const m = e.manifest;
    for (const [i, r] of m.routes.native.entries()) {
      if (r.path.includes("[")) continue;
      const local = `screen_${ident(m.slug)}_${i}`;
      imports.push(
        `import { ${r.component} as ${local} } from "${e.packageName}/native";`,
      );
      const href = nativeRouteHref(m.slug, r);
      if (m.access.check) {
        needsGate = true;
        screenRows.push(
          `  ${quote(href)}: withModuleAccess(${quote(m.access.check)}, ${local}),`,
        );
      } else {
        screenRows.push(`  ${quote(href)}: ${local},`);
      }
    }
  }
  if (needsGate)
    imports.push('import { withModuleAccess } from "./access-gate";');
  const nativeAdapterMods = nativeMods.filter(
    (e) => e.manifest.adapter?.native,
  );
  for (const e of nativeAdapterMods) {
    imports.push(
      `import { ${e.manifest.adapter?.native} as adapter_${ident(e.manifest.slug)} } from "${e.packageName}/native";`,
    );
  }
  const nativeAdapters =
    nativeAdapterMods.length === 0
      ? "[]"
      : `[\n${nativeAdapterMods
          .map(
            (e) =>
              `  { slug: ${quote(e.manifest.slug)}, target: ${quote(e.manifest.adapter?.for ?? "")}, adapter: adapter_${ident(e.manifest.slug)} },`,
          )
          .join("\n")}\n]`;
  const screens =
    screenRows.length === 0 ? "{}" : `{\n${screenRows.join("\n")}\n}`;

  const widgets =
    widgetMods.length === 0
      ? "[]"
      : `[\n${widgetMods
          .map(
            (e) =>
              `  { slug: ${quote(e.manifest.slug)}, Widget: widget_${ident(e.manifest.slug)} },`,
          )
          .join("\n")}\n]`;

  return `${ESLINT_OFF}${HEADER}${imports.join("\n")}

${SHARED_TYPES}
export const modInstalled: ModInstalled[] = ${renderInstalled(mods)};

/** Native nav defaults — the bundled first-launch menu (useNativeNav fallback). */
export const modNavDefaults: { native: ModNavDefault[] } = {
  native: ${renderNav(navLiterals(mods, "native"), "  ")},
};

/**
 * Module screens the native menu can point at (static routes), by href.
 * Rendered inside the configured tab slots (app/(app)/(tabs)/t*).
 */
export const modNativeScreens: Record<string, React.ComponentType> = ${screens};

/** Home-screen widgets declared by installed modules (native components). */
export const modWidgets: { slug: string; Widget: React.ComponentType }[] = ${widgets};

/** Native adapters (manifest adapter.native) — for ModAdaptersProvider. */
export const modClientAdapters: { slug: string; target: string; adapter: unknown }[] = ${nativeAdapters};

export function hasModule(slug: string): boolean {
  return modInstalled.some((e) => e.slug === slug);
}
`;
}

/** apps/expo/src/mod/env.generated.ts */
export function buildExpoEnv(mods: LoadedModule[]): string {
  const envMods = mods.filter(
    (e) => e.manifest.env.hasClient && e.manifest.platforms.native,
  );
  if (envMods.length === 0) {
    return `${ESLINT_OFF}${HEADER}/** Module client env (EXPO_PUBLIC_MOD_*) — none installed declare any. */
export const modEnv = {};
`;
  }

  const imports = envMods.map(
    (e) =>
      `import modEnv_${ident(e.manifest.slug)} from "${e.packageName}/env";`,
  );
  const shapeRows: string[] = [];
  const readRows: string[] = [];
  for (const e of envMods) {
    for (const key of e.envClientKeys) {
      shapeRows.push(
        `  EXPO_PUBLIC_${key}: modEnv_${ident(e.manifest.slug)}.client.${key},`,
      );
      readRows.push(`  EXPO_PUBLIC_${key}: process.env.EXPO_PUBLIC_${key},`);
    }
  }

  return `${ESLINT_OFF}${HEADER}import { z } from "zod/v4";

${imports.join("\n")}

/** Module client env (EXPO_PUBLIC_* is inlined at build time — literal reads only). */
export const modEnv = z
  .object({
${shapeRows.join("\n")}
  })
  .parse({
${readRows.join("\n")}
  });
`;
}

/** apps/nextjs/mod-packages.generated.json (transpilePackages additions). */
export function buildTranspileJson(mods: LoadedModule[]): string {
  return `${JSON.stringify(
    mods.map((e) => e.packageName),
    null,
    2,
  )}\n`;
}

/** Generated route stubs for both apps (machine-owned subtrees). */
/**
 * `export default withModuleAccess(check, Component);`, wrapped the way
 * Prettier wraps it when it doesn't fit in 80 columns (long module slugs).
 */
export function gatedDefaultExport(check: string, component: string): string {
  const line = `export default withModuleAccess(${check}, ${component});`;
  return line.length <= 80
    ? line
    : `export default withModuleAccess(\n  ${check},\n  ${component},\n);`;
}

export function buildStubs(mods: LoadedModule[]): GeneratedFile[] {
  const files: GeneratedFile[] = [];

  for (const e of mods) {
    const m = e.manifest;
    const slug = m.slug;

    if (m.platforms.web) {
      // One enabled-gating layout per distinct (group, mount base).
      const bases = new Set<string>();
      for (const r of m.routes.web) {
        const group =
          r.area === "public"
            ? MOD_PATHS.nextPublicGroup
            : MOD_PATHS.nextAppGroup;
        const base = r.mount ? r.mount.replace(/^\//, "") : `a/${slug}`;
        bases.add(`${group}/${base}`);
        const seg = r.path ? `/${r.path}` : "";
        const entry = r.rsc ? "web-server" : "web";
        // rsc pages read live data via the Payload Local API — they must never
        // be prerendered at build time (no DB/secret exists yet on a fresh
        // deploy; the old core pages were force-dynamic for the same reason).
        const dynamic = r.rsc
          ? `\nexport const dynamic = "force-dynamic";\n`
          : "";
        files.push({
          path: `${group}/${base}${seg}/page.tsx`,
          slug,
          content: `${ESLINT_OFF}${HEADER}export { ${r.component} as default } from "${e.packageName}/${entry}";\n${dynamic}`,
        });
      }
      for (const baseDir of [...bases].sort()) {
        files.push({
          path: `${baseDir}/layout.tsx`,
          slug,
          content: `${ESLINT_OFF}${HEADER}import type { ReactNode } from "react";
import { ${m.access.check ? "notFound, redirect" : "notFound"} } from "next/navigation";

${
  m.access.check
    ? `import { hasModuleAccess } from "~/lib/mod/access";
`
    : ""
}import { isModuleEnabled } from "~/lib/mod/enabled";

/** Runtime enable/disable gate — disabling the module 404s its pages. */
export default async function ModuleLayout({
  children,
}: {
  children: ReactNode;
}) {
  if (!(await isModuleEnabled(${quote(slug)}))) notFound();${
    m.access.check
      ? `
  // Access gate (manifest access.check) — users without access go home.
  if (!(await hasModuleAccess(${quote(m.access.check)}))) redirect("/a");`
      : ""
  }
  return children;
}
`,
        });
      }
    }

    if (m.platforms.native) {
      for (const r of m.routes.native) {
        // Native gating is nav-level (disabled modules disappear from the
        // menu and their APIs 404); Expo Router has no server gate to add.
        // `mount: "index"` is the app's home screen. It lives at /home: "/"
        // belongs to the host (it opens the first tab of the tab bar).
        const file =
          r.mount === "index"
            ? "home"
            : `a/${slug}/${r.path === "" ? "index" : r.path}`;
        files.push({
          path: `${MOD_PATHS.expoAppGroup}/${file}.tsx`,
          slug,
          content: m.access.check
            ? `${ESLINT_OFF}${HEADER}import { ${r.component} } from "${e.packageName}/native";

import { withModuleAccess } from "~/mod/access-gate";

// Access gate (manifest access.check) — users without access go home.
${gatedDefaultExport(quote(m.access.check), r.component)}
`
            : `${ESLINT_OFF}${HEADER}export { ${r.component} as default } from "${e.packageName}/native";\n`,
        });
      }
    }
  }

  return files.sort((a, b) => a.path.localeCompare(b.path));
}

/**
 * Copies of module Payload migrations, materialized into the host
 * migrationDir so the local `payload migrate` CLI (db:reset) applies them —
 * otherwise dev push has to reconcile renamed cms tables interactively.
 * Production applies the same names via prodMigrations; the ledger dedupes.
 */
export function buildPayloadMigrationCopies(
  mods: LoadedModule[],
): GeneratedFile[] {
  return mods.flatMap((e) =>
    e.payloadMigrations.map((m) => ({
      path: `apps/nextjs/src/payload/migrations/${m.name}.ts`,
      slug: e.manifest.slug,
      content: `// GENERATED copy (\`pnpm mod sync\`) of modules/${e.manifest.slug}/src/payload/migrations/${m.name}.ts\n// so the local \`payload migrate\` CLI applies it — do not edit.\n${m.content}`,
    })),
  );
}

/** Everything the drift test compares (registries + env + stubs + transpile list). */
export function buildAllGeneratedFiles(mods: LoadedModule[]): GeneratedFile[] {
  return [
    {
      path: MOD_PATHS.nextDataRegistry,
      content: buildNextDataRegistry(mods),
    },
    {
      path: MOD_PATHS.nextClientRegistry,
      content: buildNextClientRegistry(mods),
    },
    {
      path: MOD_PATHS.nextServerRegistry,
      content: buildNextServerRegistry(mods),
    },
    {
      path: MOD_PATHS.nextPayloadRegistry,
      content: buildNextPayloadRegistry(mods),
    },
    {
      path: MOD_PATHS.nextAdminRegistry,
      content: buildNextAdminRegistry(mods),
    },
    { path: MOD_PATHS.nextEnv, content: buildNextEnv(mods) },
    { path: MOD_PATHS.nextTranspileJson, content: buildTranspileJson(mods) },
    { path: MOD_PATHS.expoRegistry, content: buildExpoRegistry(mods) },
    { path: MOD_PATHS.expoEnv, content: buildExpoEnv(mods) },
    ...buildStubs(mods),
    ...buildPayloadMigrationCopies(mods),
  ];
}

/**
 * apps/nextjs/src/mod/lock.generated.ts — the lock, bundled, so the admin
 * Modules view can read install state on a read-only serverless filesystem.
 * "Active" detection works because a deploy that contains a new version also
 * contains this module.
 */
export function buildLockModule(lock: ModulesLock): string {
  return `${ESLINT_OFF}${HEADER}/** The committed modules.lock, inlined for serverless reads. */
export const modulesLock = ${JSON.stringify(lock, null, 2)} as const;
`;
}

const ENV_FENCE_START = "# --- modules (generated) ---";
const ENV_FENCE_END = "# --- end modules (generated) ---";

/** The fenced .env.example block listing module env vars. */
export function buildEnvExampleBlock(mods: LoadedModule[]): string {
  const lines: string[] = [
    ENV_FENCE_START,
    "# Managed by `pnpm mod sync` — do not edit between these markers.",
    '# Uncomment + set per module; unset optional vars must stay ABSENT (not "").',
  ];
  for (const e of mods) {
    if (e.envServerKeys.length === 0 && e.envClientKeys.length === 0) continue;
    lines.push("", `# ${e.manifest.name} (${e.manifest.slug})`);
    for (const key of e.envServerKeys) lines.push(`# ${key}=`);
    for (const key of e.envClientKeys) {
      lines.push(`# NEXT_PUBLIC_${key}=`, `# EXPO_PUBLIC_${key}=`);
    }
  }
  lines.push(ENV_FENCE_END);
  return lines.join("\n");
}

/** Replace (or append) the fenced block inside the .env.example content. */
export function applyEnvExampleBlock(current: string, block: string): string {
  const start = current.indexOf(ENV_FENCE_START);
  const end = current.indexOf(ENV_FENCE_END);
  if (start !== -1 && end !== -1 && end > start) {
    return `${current.slice(0, start)}${block}${current.slice(end + ENV_FENCE_END.length)}`;
  }
  const sep = current.endsWith("\n") ? "\n" : "\n\n";
  return `${current}${sep}${block}\n`;
}
